import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.Aev9KvMf.js";const b=JSON.parse('{"title":"药品批准文号查询 · 识别假药","description":"药品真假官方查询教程：NMPA 数据查询平台核对药品批准文号（国药准字），识别假药与非法渠道药品。","frontmatter":{"title":"药品批准文号查询 · 识别假药","issuer":"国家药品监督管理局","source_tier":"一级来源","version":"—","published":"—","source_url":"https://www.nmpa.gov.cn/datasearch/home-index.html","status":"现行服务","tags":["官方查询","药品","防坑","批准文号"],"type":"查询页","reviewed":false,"description":"药品真假官方查询教程：NMPA 数据查询平台核对药品批准文号（国药准字），识别假药与非法渠道药品。"},"headers":[],"relativePath":"query/drug.md","filePath":"query/drug.md"}'),o={name:"query/drug.md"};function h(l,t,n,s,i,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="药品批准文号查询-·-识别假药" tabindex="-1">药品批准文号查询 · 识别假药 <a class="header-anchor" href="#药品批准文号查询-·-识别假药" aria-label="Permalink to &quot;药品批准文号查询 · 识别假药&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页由 AI 依据官方平台公开信息整理，查询步骤请以平台实际页面为准；平台入口改版时以药监局官网为准。</p></div><blockquote><p><strong>官方入口</strong>：国家药品监督管理局<a href="https://www.nmpa.gov.cn/datasearch/home-index.html" target="_blank" rel="noreferrer">数据查询平台</a>（选&quot;药品&quot;分类：国产药品/进口药品/药品通用名等子库）。· 一级来源</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>合法药品包装上都有<strong>批准文号：国药准字 H/Z/S/B + 8 位数字</strong>（H 化学药、Z 中药、S 生物制品、B 保健药品旧类）。文号查不到或与产品不符 = 高度怀疑假药。<strong>用药疑虑请同时咨询医生或药师。</strong></p><h2 id="_30-秒查询步骤-待核验" tabindex="-1">30 秒查询步骤（待核验） <a class="header-anchor" href="#_30-秒查询步骤-待核验" aria-label="Permalink to &quot;30 秒查询步骤（待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>怎么做</th></tr></thead><tbody><tr><td>1</td><td>打开 <a href="https://www.nmpa.gov.cn/datasearch/home-index.html" target="_blank" rel="noreferrer">NMPA 数据查询平台</a>，选&quot;药品&quot;</td></tr><tr><td>2</td><td>选子库（国产药品/进口药品），输入&quot;国药准字&quot;文号或药品通用名</td></tr><tr><td>3</td><td>核对结果：<strong>通用名、剂型、规格、生产企业、批准文号</strong>与手里药品是否一致</td></tr></tbody></table><h2 id="结果怎么读" tabindex="-1">结果怎么读 <a class="header-anchor" href="#结果怎么读" aria-label="Permalink to &quot;结果怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>看到什么</th><th>说明</th></tr></thead><tbody><tr><td>文号与厂家完全一致</td><td>正常（<a href="https://www.nmpa.gov.cn/datasearch/home-index.html" target="_blank" rel="noreferrer">数据查询平台</a>）</td></tr><tr><td>查无此文号</td><td>假药高度可疑，保留证据并向药监部门举报</td></tr><tr><td>名称一致但厂家不符</td><td>套号风险，警惕</td></tr></tbody></table><h2 id="避坑要点" tabindex="-1">避坑要点 <a class="header-anchor" href="#避坑要点" aria-label="Permalink to &quot;避坑要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>骗局话术</th><th>官方依据</th></tr></thead><tbody><tr><td>&quot;祖传秘方/纯天然无副作用特效药&quot;</td><td>正规药品必须有国药准字，宣称&quot;包治&quot;的查证后多为假药</td></tr><tr><td>&quot;微信代购国外真药&quot;</td><td>未取得批准文号的境外药品按现行法规不得在国内销售</td></tr><tr><td>【本站提示】网售药品认准平台资质公示，收货核对文号</td><td>—</td></tr></tbody></table><h2 id="相关查询" tabindex="-1">相关查询 <a class="header-anchor" href="#相关查询" aria-label="Permalink to &quot;相关查询&quot;">​</a></h2><ul><li>化妆品：<a href="/SageRelay/query/cosmetics.html">化妆品备案/注册查询</a></li><li>保健食品：<a href="/SageRelay/query/health-food.html">保健食品注册备案查询</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>平台</td><td>国家药品监督管理局数据查询平台（一级来源）</td></tr><tr><td>入口</td><td><a href="https://www.nmpa.gov.cn/datasearch/home-index.html" target="_blank" rel="noreferrer">nmpa.gov.cn/datasearch</a>（入口以药监局官网为准）</td></tr></tbody></table>',15)])])}const m=a(o,[["render",h]]);export{b as __pageData,m as default};
